def even_binomial_Coeff_Sum(n):
    """
    Calculate the sum of even index binomial coefficients for a given positive integer n.
    The binomial coefficients are from the expansion of (1 + 1)^n = C(n, 0) + C(n, 1) + ... + C(n, n).
    Here we sum coefficients at even indices: C(n, 0) + C(n, 2) + C(n, 4) + ...
    """
    if n % 4 == 0 or n % 4 == 1:
        return 2**(n - 1)
    else:
        return 2**n - 2**(n - 1)
