def even_binomial_Coeff_Sum(n):
    total = 0
    for k in range(0, n + 1, 2):
        # Calculate binomial coefficient C(n, k)
        binom_coeff = 1
        if k > n - k:
            k = n - k  # Take advantage of symmetry to reduce computations
        for i in range(1, k + 1):
            binom_coeff = binom_coeff * (n - k + i) // i
        total += binom_coeff
    return total
